def _components(grid, bg):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    nx, ny = x + dx, y + dy
                    if (0 <= nx < h and 0 <= ny < w and
                        (nx, ny) not in seen and grid[nx][ny] == color):
                        seen.add((nx, ny))
                        q.append((nx, ny))
            out.append((color, cells))
    return out

def _norm(cells):
    r0 = min(r for r, c in cells)
    c0 = min(c for r, c in cells)
    return frozenset((r-r0, c-c0) for r, c in cells)

def _is_key_l(cells):
    rs = [r for r, c in cells]
    cs = [c for r, c in cells]
    # The key is the prominent orthogonal L/bar object: it has long straight
    # horizontal and vertical runs meeting at a corner.
    by_r = {}
    by_c = {}
    for r, c in cells:
        by_r.setdefault(r, set()).add(c)
        by_c.setdefault(c, set()).add(r)
    max_row = max(map(len, by_r.values()))
    max_col = max(map(len, by_c.values()))
    return max_row >= 3 and max_col >= 4 and (max_row + max_col >= 9)

def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    counts = {}
    for row in g:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    comps = _components(g, bg)
    keys = [(i, color, cells) for i, (color, cells) in enumerate(comps) if _is_key_l(cells)]
    if not keys:
        return g
    # In ARC instances the key L is the longest such line-object.
    key_i, paint, key_cells = max(keys, key=lambda x: len(x[2]))
    shapes = {}
    for i, (color, cells) in enumerate(comps):
        if i == key_i:
            continue
        shapes.setdefault(_norm(cells), []).append((i, color, cells))
    # Duplicate silhouettes are examples and targets; recolor the later copy.
    candidates = []
    for same in shapes.values():
